<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Services\MarketResearchCrudService;use App\Support\MarketResearchCrudDefinitions as Defs;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
final class MarketResearchCrudController extends Controller { public function __construct(private readonly MarketResearchCrudService $service){} public function confirmation(Request $r,string $entity):JsonResponse{$d=$r->validate(['action'=>['required','in:create,update,archive,delete_permanent'],'client_id'=>['required','integer','min:1'],'record_id'=>['sometimes','integer','min:0'],'payload'=>['required','array']]);return response()->json(['data'=>$this->service->confirmation($r->user(),$entity,$d['action'],(int)$d['client_id'],(int)($d['record_id']??0),$d['payload'])]);} public function store(Request $r,string $entity):JsonResponse{$d=$r->validate($this->rules($entity,true));return response()->json(['data'=>$this->service->create($r->user(),$entity,$d),'meta'=>['operation'=>'create']],201);} public function update(Request $r,string $entity,int $record):JsonResponse{$d=$r->validate($this->rules($entity,false));return response()->json(['data'=>$this->service->update($r->user(),$entity,$record,$d),'meta'=>['operation'=>'update']]);} public function archive(Request $r,string $entity,int $record):JsonResponse{$d=$r->validate(['confirmation_token'=>['required','string','size:64'],'reason'=>['required','string','min:5','max:500']]);return response()->json(['data'=>$this->service->archive($r->user(),$entity,$record,$d),'meta'=>['operation'=>'archive']]);} public function deletePermanent(Request $r,string $entity,int $record):JsonResponse{$d=$r->validate(['client_id'=>['required','integer','min:1'],'confirmation_token'=>['required','string','size:64'],'reason'=>['required','string','min:5','max:500']]);return response()->json(['data'=>$this->service->deletePermanent($r->user(),$entity,$record,$d),'meta'=>['operation'=>'delete_permanent']]);} private function rules(string $entity,bool $create):array{$def=Defs::get($entity);$rules=['client_id'=>['required','integer','min:1'],'confirmation_token'=>['required','string','size:64']];foreach($def['fields'] as $f)$rules[$f]=[($create&&in_array($f,$def['required'],true))?'required':'sometimes','nullable','string','max:2000'];return $rules;} }
